import { KDSOrder } from '../../types/kds';
import { SourceBadge } from './SourceBadge';

interface Props {
    order: KDSOrder;
}

export function OrderTicket({ order }: Props) {
    // Production visual states logic
    const getBorderState = () => {
        if (order.isDelayed) return 'border-red-600 border-[4px]';
        if (order.stage === 'READY') return 'border-green-500 border-[4px]';
        if (order.stage === 'PREPARING') return 'border-[#1FA4A9] border-[4px]';
        return 'border-slate-200 border-[1px]';
    };

    const formatCreatedAt = (dateStr: string) => {
        try {
            const date = new Date(dateStr);
            return date.toLocaleTimeString('en-US', {
                hour: '2-digit',
                minute: '2-digit',
                hour12: false
            });
        } catch {
            return '--:--';
        }
    };

    return (
        <div
            className={`kds-ticket bg-white rounded-xl shadow-xl flex flex-col min-h-[280px] overflow-hidden transition-all duration-200 ${getBorderState()}`}
        >
            {/* TOP ROW */}
            <div className="p-4 bg-slate-50 border-bottom border-slate-100 flex justify-between items-start">
                <div className="flex flex-col gap-1">
                    <h2 className="text-[28px] leading-tight font-black text-slate-950">
                        #{order.orderNumber}
                    </h2>
                    <div>
                        <SourceBadge source={order.order_source} />
                    </div>
                </div>
                <div className="text-right">
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-tighter">
                        CREATED: {formatCreatedAt(order.createdAt)}
                    </span>
                </div>
            </div>

            {/* SECOND ROW */}
            <div className="px-4 py-2 bg-slate-100 flex justify-between items-center border-y border-slate-200">
                <span className="text-sm font-black text-slate-700 uppercase tracking-widest">
                    {order.fulfillment_type.replace(/_/g, ' ')}
                </span>
                <span className="px-2 py-0.5 bg-slate-800 text-white text-[10px] font-black rounded uppercase tracking-widest">
                    {order.stage}
                </span>
            </div>

            {/* MIDDLE SECTION - ITEM LIST */}
            <div className="p-4 flex-1 overflow-y-auto max-h-[400px]">
                <div className="space-y-4">
                    {order.items.map((item, idx) => (
                        <div key={idx} className="border-b border-slate-50 last:border-0 pb-3 last:pb-0">
                            <div className="flex items-start gap-2">
                                <span className="text-[20px] font-black text-slate-900 leading-none mt-1">
                                    1x
                                </span>
                                <div className="flex flex-col">
                                    <span className="text-[20px] font-bold text-slate-900 leading-tight">
                                        {item.name}
                                    </span>
                                    {item.variant && (
                                        <span className="text-sm font-semibold text-slate-500 italic">
                                            {item.variant}
                                        </span>
                                    )}
                                </div>
                            </div>

                            {/* Modifiers */}
                            {item.modifiers.length > 0 && (
                                <div className="ml-8 mt-2 space-y-1">
                                    {item.modifiers.map((mod, modId) => (
                                        <div key={modId} className="flex items-center gap-2 text-md font-bold text-slate-600">
                                            <span className="text-blue-500">+</span>
                                            <span>{mod.name}</span>
                                            <span className="text-[10px] px-1.5 py-0.5 bg-slate-200 text-slate-500 rounded uppercase">
                                                {mod.placement || 'FULL'}
                                            </span>
                                        </div>
                                    ))}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>

            {/* BOTTOM SECTION */}
            <div className="p-4 mt-auto border-t border-slate-200 bg-slate-50 flex flex-col gap-3">
                <div className="flex justify-between items-center">
                    <div className="flex flex-col">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">EST. READY</span>
                        <span className="text-xl font-black text-slate-800 tracking-tight">
                            {order.estimatedReadyTime}
                        </span>
                    </div>
                    <div className="text-right flex flex-col items-end">
                        <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">TIMER</span>
                        <span className="text-2xl font-black text-red-600 tabular-nums">
                            00:00
                        </span>
                    </div>
                </div>

                {/* Action Button Placeholder */}
                <button className="w-full bg-slate-950 text-white h-[60px] rounded-xl font-black uppercase tracking-widest text-sm hover:bg-slate-800 active:scale-[0.98] transition-all">
                    BUMP TICKET
                </button>
            </div>
        </div>
    );
}
